

# This file was *autogenerated* from the file bz2Decoder.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_40 = Integer(40); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_8 = Integer(8); _sage_const_31 = Integer(31); _sage_const_16 = Integer(16)
import bz2
import re
import os
from sage.all import GF, PolynomialRing

def save_system_to_file(input_path, ring, equations):
    """
    Saves the reconstructed MQ system to a .txt file with the same base name.
    """
    # Generate output path: /path/to/file.bz2 -> /path/to/file.txt
    base_dir = os.path.dirname(input_path)
    base_name = os.path.basename(input_path).split('.')[_sage_const_0 ]
    output_path = os.path.join(base_dir, f"{base_name}.txt")
    
    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(f"# MQ Challenge System Export\n")
            f.write(f"# Source: {os.path.basename(input_path)}\n")
            f.write(f"# Field: {ring.base_ring()}\n")
            f.write(f"# Variables (n): {ring.ngens()}\n")
            f.write(f"# Equations (m): {len(equations)}\n")
            f.write("-" * _sage_const_40  + "\n")
            
            for i, poly in enumerate(equations):
                f.write(f"f[{i}] = {poly}\n")
        
        print(f"Successfully saved system to: {output_path}")
    except Exception as e:
        print(f"Failed to write file: {e}")

def parse_mq_challenge(file_path):
    """
    Parses Fukuoka MQ Challenge files and reconstructs the algebraic system.
    """
    # Load content
    try:
        if file_path.endswith('.bz2'):
            with bz2.open(file_path, 'rt', encoding='utf-8') as f:
                content = f.read()
        else:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
    except Exception as e:
        print(f"Read Error: {e}")
        return None, None

    # Robust Metadata Extraction
    try:
        gf_info = re.search(r'Galois Field\s*:\s*(.*)', content, re.I).group(_sage_const_1 )
        n = int(re.search(r'\(n\)\s*:\s*(\d+)', content, re.I).group(_sage_const_1 ))
        m = int(re.search(r'\(m\)\s*:\s*(\d+)', content, re.I).group(_sage_const_1 ))
    except (AttributeError, ValueError):
        print("Formatting Error: Metadata not found in header.")
        return None, None

    # Finite Field Definition
    if "256" in gf_info or "x^8" in gf_info:
        # Modulus for GF(2^8): x^8 + x^4 + x^3 + x + 1
        K = GF(_sage_const_2 **_sage_const_8 , name='a', modulus=[_sage_const_1 , _sage_const_1 , _sage_const_0 , _sage_const_1 , _sage_const_1 , _sage_const_0 , _sage_const_0 , _sage_const_0 , _sage_const_1 ])
        mode = "GF(256)"
    elif "31" in gf_info:
        K = GF(_sage_const_31 )
        mode = "GF(31)"
    else:
        K = GF(_sage_const_2 )
        mode = "GF(2)"

    # Polynomial Ring and Monomial Order
    R = PolynomialRing(K, n, 'x')
    vars = R.gens()

    # Monomial Sequence: 1, x1...xn, x1*x1, x1*x2...x1*xn, x2*x2...xn*xn
    monomials = [R(_sage_const_1 )] + list(vars)
    for i in range(n):
        for j in range(i, n):
            monomials.append(vars[i] * vars[j])

    # Parse Data Segment
    data_parts = content.split('*********************')
    if len(data_parts) < _sage_const_2 :
        print("Error: Coefficient segment separator missing.")
        return None, None
    
    data_segment = data_parts[-_sage_const_1 ].strip()
    
    if mode == "GF(256)":
        raw_vals = re.findall(r'[0-9a-fA-F]+', data_segment)
        coeffs = [K(int(h, _sage_const_16 )) for h in raw_vals]
    else:
        raw_vals = re.findall(r'\d+', data_segment)
        coeffs = [K(int(d)) for d in raw_vals]

    # Reconstruct Equations
    equations = []
    num_coeffs = len(monomials)
    for i in range(m):
        chunk = coeffs[i*num_coeffs : (i+_sage_const_1 )*num_coeffs]
        if len(chunk) == num_coeffs:
            poly = sum(c * m for c, m in zip(chunk, monomials))
            equations.append(poly)

    return R, equations

